import http from 'node:http';let mode='good';let calls=0;
const server=http.createServer(async(req,res)=>{res.setHeader('Content-Type','application/json');if(req.url==='/test-mode'){let raw='';for await(const c of req)raw+=c;mode=JSON.parse(raw).mode;res.end(JSON.stringify({mode,calls}));return;}if(req.url==='/api/tags'){res.end(JSON.stringify({models:[{name:'qa-fixture'}]}));return;}if(req.url==='/api/generate'){calls++;for await(const c of req){}if(mode==='error'){res.statusCode=503;res.end('{}');return;}res.end(JSON.stringify({response:mode==='invalid'?'null':JSON.stringify({summary:'[Kiểm thử] Phòng có thông tin để Admin xem xét.',riskLevel:'medium',missingInformation:['hợp đồng'],suggestedPrice:2500000,suggestedArea:25.5,location:'Hải Châu'})}));return;}res.statusCode=404;res.end('{}');});server.listen(11435,'127.0.0.1',()=>console.log('Synthetic Ollama fixture on loopback 11435. Not a real model.'));
